import re
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.rows = []
        self.current_row = []

    def handle_starttag(self, tag, attrs):
        if tag == 'td':
            self.in_td = True

    def handle_endtag(self, tag):
        if tag == 'td':
            self.in_td = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = []

    def handle_data(self, data):
        if self.in_td:
            self.current_row.append(data.strip())

html_content = open('/app/resources/treasury_bulletin_1980_05_page_41.txt').read()

parser = TableParser()
parser.feed(html_content)

# First table: rows 0-22 (23 rows)
# Second table: rows 23-45 (23 rows)

table1_rows = parser.rows[0:23]
table2_rows = parser.rows[23:46]

def count_leading_one(rows):
    count = 0
    for row in rows:
        # Skip first column (row header = year/month)
        for val in row[1:]:
            if val == '*' or val == '':
                continue
            # First, remove trailing non-numeric chars (like 'r' or '7/' for footnotes)
            clean_val = re.sub(r'[^0-9.].*$', '', val)
            # Then remove thousands separators (commas)
            clean_val = clean_val.replace(',', '')
            # Now check if the first digit is '1'
            if clean_val and len(clean_val) > 0:
                # Handle decimal numbers - take integer part
                if '.' in clean_val:
                    integer_part = clean_val.split('.')[0]
                    if integer_part and integer_part[0] == '1':
                        count += 1
                        print(f"  Found: {val} -> {clean_val} (leading 1)")
                else:
                    if clean_val[0] == '1':
                        count += 1
                        print(f"  Found: {val} -> {clean_val} (leading 1)")
    return count

print("Table 1 values starting with 1:")
t1_count = count_leading_one(table1_rows)
print(f"\nTable 1 count: {t1_count}")

print("\n" + "="*50)
print("\nTable 2 values starting with 1:")
t2_count = count_leading_one(table2_rows)
print(f"\nTable 2 count: {t2_count}")

print(f"\nTotal: {t1_count + t2_count}")
